# final_edit.py -- reproduces patch "final" (edit E5) from base weights in the WSP kernel namespace.
# Edit: rank-1 direction removal on selected MLP down_proj output columns (two rounds).
#   W[:, idx] <- W[:, idx] - u u^T W[:, idx]   (u = unit "loop-vs-normal" residual direction at element-start positions)
# Round 1: u1 = dirsD (computed from baseline loops), layers 15,17,19,21,23, top-128 neurons/layer.
# Round 2: u2 = dirsD2 (recomputed on round-1-edited model from its remaining loops), same layers, top-32 neurons/layer.
# Directions (float32) and neuron indices are embedded below (torch.save + base64).
import io, base64, torch
reset_weights()
SPEC_B64 = ""
spec = torch.load(io.BytesIO(base64.b64decode(SPEC_B64)))
P = dict(model.named_parameters())
for rnd in (1, 2):
    for l in spec['layers']:
        u = spec['u%d' % rnd][l].to('cuda').float()
        idx = torch.tensor(spec['idx%d' % rnd][l], device='cuda')
        W = P[f'language_model.model.layers.{l}.mlp.down_proj.weight'].data
        Wf = W[:, idx].float()
        Wf -= u[:, None] * (u @ Wf)[None, :]
        W[:, idx] = Wf.to(W.dtype)
print(changed_weights()['changed'])
